const Wolf=React.memo(function Wolf({position,target={x:0,z:0},elite=false}){
  const ref=useRef(), legs=useRef([]), phase=useRef(0);
  const home=useRef({x:position[0],z:position[2]});
  useFrame(({clock},dt)=>{if(ref.current){const dx=target.x-ref.current.position.x,dz=target.z-ref.current.position.z,d=Math.hypot(dx,dz);const chasing=d>2.1&&d<13;if(chasing&&d>.001){const step=Math.min(dt*(elite?1.25:.72),Math.max(0,d-1.65));ref.current.position.x+=dx/d*step;ref.current.position.z+=dz/d*step;ref.current.rotation.y=Math.atan2(dx,dz);}else{const t=clock.elapsedTime*(elite?.42:.28)+(elite?1.3:0);const px=home.current.x+Math.cos(t)*1.8,pz=home.current.z+Math.sin(t*.8)*1.4,pdx=px-ref.current.position.x,pdz=pz-ref.current.position.z,pd=Math.hypot(pdx,pdz);if(pd>.12){const step=Math.min(dt*.5,pd);ref.current.position.x+=pdx/pd*step;ref.current.position.z+=pdz/pd*step;ref.current.rotation.y=Math.atan2(pdx,pdz);}}ref.current.position.y=.34+Math.abs(Math.sin(clock.elapsedTime*(chasing?8:3)))*.035;if(elite)ref.current.scale.setScalar(1.12);phase.current+=dt*(chasing?11:3);}legs.current.forEach((leg,i)=>{if(leg)leg.rotation.x=Math.sin(phase.current+(i%2)*Math.PI)*.42;});});
  return <group ref={ref} position={position}>
    <mesh castShadow><boxGeometry args={[.92,.5,1.22]}/><meshToonMaterial color="#66547f"/></mesh>
    <mesh position={[0,.28,-.38]} castShadow><boxGeometry args={[.56,.42,.54]}/><meshToonMaterial color="#917eb0"/></mesh>
    <mesh position={[-.18,.55,-.52]} rotation={[0,0,-.18]}><coneGeometry args={[.12,.32,5]}/><meshToonMaterial color="#917eb0"/></mesh><mesh position={[.18,.55,-.52]} rotation={[0,0,.18]}><coneGeometry args={[.12,.32,5]}/><meshToonMaterial color="#917eb0"/></mesh>
    <mesh position={[-.13,.31,-.65]}><sphereGeometry args={[.045,8,8]}/><meshBasicMaterial color="#ff4b73"/></mesh><mesh position={[.13,.31,-.65]}><sphereGeometry args={[.045,8,8]}/><meshBasicMaterial color="#ff4b73"/></mesh>
    {[-.31,.31].map(x=>[-.35,.35].map(z=><mesh key={`${x}-${z}`} ref={el=>{legs.current[(x>0?2:0)+(z>0?1:0)]=el;}} position={[x,-.25,z]}><capsuleGeometry args={[.09,.35,3,6]}/><meshToonMaterial color="#554465"/></mesh>))}
    <mesh position={[0,.12,.72]} rotation={[.8,0,0]}><capsuleGeometry args={[.09,.52,3,6]}/><meshToonMaterial color="#8b78a7"/></mesh>
  </group>;
});

