function WaterSurface({ position=[0,0,0], size=[34,8], color='#267d9d', opacity=.82 }) {
 const material=useRef();
 useFrame(({clock})=>{if(material.current?.userData?.shader){material.current.userData.shader.uniforms.uWhiskayTime.value=clock.elapsedTime;}});
 return <mesh rotation={[-Math.PI/2,0,0]} position={position} receiveShadow><planeGeometry args={size}/><meshStandardMaterial ref={material} color={color} roughness={.2} metalness={.12} transparent opacity={opacity} onBeforeCompile={shader=>{shader.uniforms.uWhiskayTime={value:0};material.current&&(material.current.userData.shader=shader);shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nuniform float uWhiskayTime; varying vec2 vWhiskayUv;').replace('#include <begin_vertex>','#include <begin_vertex>\nvWhiskayUv=uv; transformed.z += sin(uv.x*18.0+uWhiskayTime*1.7)*0.025 + cos(uv.y*13.0-uWhiskayTime)*0.018;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nuniform float uWhiskayTime; varying vec2 vWhiskayUv;').replace('#include <color_fragment>','#include <color_fragment>\nfloat ripple=0.94+0.06*sin(vWhiskayUv.x*24.0+vWhiskayUv.y*16.0+uWhiskayTime*2.0); diffuseColor.rgb*=ripple;');}}/></mesh>;
}
