function NightWisp({position=[0,0,0],target={x:0,z:0}}){const ref=useRef();useFrame(({clock},dt)=>{if(!ref.current)return;const safe=Math.min(dt,.05),dx=target.x-ref.current.position.x,dz=target.z-ref.current.position.z,d=Math.hypot(dx,dz);if(d>3&&d<12&&d>.001){ref.current.position.x+=dx/d*safe*.34;ref.current.position.z+=dz/d*safe*.34;}ref.current.position.y=.7+Math.sin(clock.elapsedTime*2.4)*.14;ref.current.rotation.y+=safe*.4;});return <group ref={ref} position={position}><mesh><octahedronGeometry args={[.38,1]}/><meshStandardMaterial color="#91b9ff" emissive="#596eff" emissiveIntensity={1.6} transparent opacity={.88}/></mesh><pointLight color="#758cff" intensity={.8} distance={4}/><Html position={[0,.65,0]} center distanceFactor={13}><span style={{fontSize:9,padding:'2px 5px',borderRadius:5,background:'#08152bde',color:'#cbd7ff',border:'1px solid #778cff'}}>Night Wisp</span></Html></group>;}
