function FollowCamera({ position, yaw }) {
  const { camera } = useThree();
  useFrame((_, dt) => {
    const distance = 7.5, height = 4.2;
    const desired = new THREE.Vector3(position.x + Math.sin(yaw) * distance, height, position.z + Math.cos(yaw) * distance);
    camera.position.lerp(desired, 1 - Math.exp(-6 * Math.min(dt, .05)));
    camera.lookAt(position.x, 1.0, position.z);
  });
  return null;
}

